begin;
create table public.template_forms (
 template_id text primary key references public.template_catalog(id),
 template_version_id uuid not null references public.template_versions(id),
 revision integer not null default 1 check(revision>0),
 definition jsonb not null check(jsonb_typeof(definition)='object'),
 updated_at timestamptz not null default now(),
 updated_by uuid references auth.users(id)
);
alter table public.template_forms enable row level security;
revoke all on public.template_forms from anon,authenticated;
grant all on public.template_forms to service_role;
alter table public.invitations add column form_step_id text;
alter table public.invitations add column form_revision integer;

create function public.fmi_save_template_form(p_template text,p_version uuid,p_revision integer,p_definition jsonb,p_actor uuid) returns jsonb
language plpgsql security invoker set search_path=public as $$
declare f template_forms;begin
 perform 1 from template_catalog where id=p_template for update;
 if not found or not exists(select 1 from template_versions where id=p_version and template_id=p_template) then raise exception 'Template mismatch';end if;
 if not exists(select 1 from cms_operators where user_id=p_actor and active) then raise exception 'Operator required';end if;
 select * into f from template_forms where template_id=p_template;
 if coalesce(f.revision,0)<>p_revision then raise exception 'Form changed; reload';end if;
 insert into template_forms(template_id,template_version_id,revision,definition,updated_by)
 values(p_template,p_version,p_revision+1,p_definition,p_actor)
 on conflict(template_id) do update set template_version_id=excluded.template_version_id,revision=excluded.revision,definition=excluded.definition,updated_at=now(),updated_by=p_actor returning * into f;
 return to_jsonb(f);end$$;

create function public.fmi_save_form_draft(p_slug text,p_owner uuid,p_revision integer,p_content jsonb,p_step text,p_form_revision integer,p_new_slug text) returns jsonb
language plpgsql security invoker set search_path=public as $$
declare r invitations;begin
 select * into r from invitations where slug=p_slug and owner_id=p_owner and template_version_id is not null for update;
 if not found or r.deleted_at is not null then raise exception 'Invitation not found';end if;
 if r.draft_revision<>p_revision then raise exception 'Draft changed; reload before saving';end if;
 if r.first_published_at is not null and r.expires_at+interval '90 days'<=now() then raise exception 'Recovery period ended';end if;
 if r.first_published_at is not null and p_new_slug<>r.slug then raise exception 'Published address cannot change';end if;
 if not exists(select 1 from template_forms where template_version_id=r.template_version_id and revision=p_form_revision) then raise exception 'Form changed; reload';end if;
 update invitations set slug=p_new_slug,draft_content=p_content,form_step_id=p_step,form_revision=p_form_revision,draft_revision=draft_revision+1,updated_at=now() where id=r.id returning * into r;
 return to_jsonb(r);end$$;
revoke all on function public.fmi_save_template_form(text,uuid,integer,jsonb,uuid),public.fmi_save_form_draft(text,uuid,integer,jsonb,text,integer,text) from public,anon,authenticated;
grant execute on function public.fmi_save_template_form(text,uuid,integer,jsonb,uuid),public.fmi_save_form_draft(text,uuid,integer,jsonb,text,integer,text) to service_role;
